def is_valid_token_format(token: str) -> bool:
    """BUGGY: Accepts tokens with 2 or more dots (more than 3 segments)."""
    import re

    if not isinstance(token, str):
        return False
    if token == "":
        return False

    # Does not strictly enforce dot count.
    if token.count(".") < 2:
        return False

    parts = token.split(".")

    base64url_re = re.compile(r"^[A-Za-z0-9_-]+$")
    for part in parts:
        if part == "":
            return False
        if base64url_re.fullmatch(part) is None:
            return False

    return True

def is_valid_token_format(token: str) -> bool:
    """BUGGY: Does not reject empty segments."""
    import re

    if not isinstance(token, str):
        return False
    if token == "":
        return False

    if any(ch.isspace() for ch in token):
        return False

    if token.count(".") != 2:
        return False

    parts = token.split(".")
    if len(parts) != 3:
        return False

    base64url_re = re.compile(r"^[A-Za-z0-9_-]*$")
    # NOTE: `*` allows empty segment; and there's no explicit non-empty check.
    for part in parts:
        if base64url_re.fullmatch(part) is None:
            return False

    return True

def is_valid_token_format(token: str) -> bool:
    """BUGGY: Uses `isalnum()` so '-' and '_' are rejected."""

    if not isinstance(token, str):
        return False
    if token == "":
        return False

    if any(ch.isspace() for ch in token):
        return False

    if token.count(".") != 2:
        return False

    parts = token.split(".")
    if len(parts) != 3:
        return False

    for part in parts:
        if part == "":
            return False
        if not part.isalnum():
            return False

    return True

